import {paintMosaicStudy} from './mosaic-details.js?v=41.0.0';
import {paintWaystation} from './waystation-details.js?v=40.0.0';
import {createMallGroundCanvas} from './mall-environment.js?v=43.0.0';
import {themeFor} from './mall-design.js?v=35.0.0';
// Code-native mall scenery: architecture, activities and animation, never fictional merchandise.
export const VENUE_LABELS={rest:'Garden benches',coffee:'Coffee terrace',food:'Food hall',popup:'Pop-up pavilion',services:'Guest services',photo:'Photo spot',bridge:'Garden bridge',carousel:'Carousel',flowers:'Flower studio',cinema:'Cinema',art:'Sculpture court',lounge:'Tea terrace'};
export function paintMallGround(w){if(w.layout.campus){const c=w.ctx;w.campusGround??=createMallGroundCanvas(w.layout);c.drawImage(w.campusGround,0,0,w.layout.width,w.layout.height);for(const n of w.layout.campus.courts)w.fitText(n.label,n.x,n.y-40,210,13,themeFor(w.layout.family).accent);for(const r of w.layout.planters)w.round(r.x,r.y,r.width,r.height,8,'#819d75');return;}const {ctx:c,layout:{plan},state:s}=w,outdoor=['orange','citadel','spectrum','desert','island','century'].includes(s.mallId);w.round(12,20,1176,860,45,outdoor?'#eee7d4':'#ebe6d9');
 // The entire court floor is open to explore. Planted islands and buildings are solid fixtures.
 c.save();c.beginPath();c.rect(24,36,1152,834);c.clip();for(let x=24;x<1200;x+=40)w.line(x,36,x,870,'#c8bea422',1);for(let y=36;y<900;y+=40)w.line(24,y,1176,y,'#c8bea422',1);c.restore();
 for(const e of plan.edges){const a=plan.nodes[Number(e.a)],b=plan.nodes[Number(e.b)];w.line(a.x,a.y,b.x,b.y,outdoor?'#c1c9ad':'#c1c7b8',e.width+35);w.line(a.x,a.y,b.x,b.y,outdoor?'#ecdfc6':'#f0e9dc',e.width+34);w.line(a.x,a.y,b.x,b.y,outdoor?'#f5e9cf':'#faf5e9',e.width+16);w.line(a.x,a.y,b.x,b.y,'#d8c9ad',2);
 const length=Math.hypot(a.x-b.x,a.y-b.y),dx=(b.x-a.x)/length,dy=(b.y-a.y)/length;for(let step=30;step<length;step+=28){const x=a.x+dx*step,y=a.y+dy*step;w.line(x-dy*37,y+dx*37,x+dy*37,y-dx*37,'#c5b99740',1);}}
 for(let i=0;i<plan.nodes.length;i++){const n=plan.nodes[i];w.ellipse(n.x,n.y,55,50,outdoor?'#ecdfc4':'#e4d6ba');w.ellipse(n.x,n.y,48,43,'#f8eed7');w.ellipse(n.x,n.y,30,27,'#d6c7a6');w.ellipse(n.x,n.y,28,25,'#f0e5cb');if(i%3===0){w.ellipse(n.x,n.y,18,15,'#bda677');w.ellipse(n.x,n.y,14,12,'#e5dbc3');w.line(n.x-9,n.y,n.x+9,n.y,'#bca77e',2);w.line(n.x,n.y-8,n.x,n.y+8,'#bca77e',2);}else{c.save();c.translate(n.x,n.y);c.rotate(Math.PI/4);w.round(-8,-8,16,16,2,'#bda479');c.restore();}}
 for(const r of w.layout.planters){const x=r.x+r.width/2,y=r.y+r.height/2;w.round(r.x,r.y,r.width,r.height,7,'#b7b98f');w.ellipse(x,y-3,17,13,'#7d9e72');w.ellipse(x-5,y-8,10,8,'#a2bf88');}

}
export function paintFacade(w,st,anchor=false){const {ctx:c}=w,x=st.x,y=st.y,sw=st.width,sh=st.height,col=anchor?'#788c79':st.color||'#7f947a';w.line(x+sw/2,y+sh/2,st.door.x,st.door.y,'#e9dfc8',12);w.round(x+4,y+7,sw,sh,7,'#4057462a');w.round(x,y,sw,sh,7,anchor?'#ece5d3':st.light||'#f1e4cd');w.round(x,y,sw,24,5,col);c.fillStyle='#ffffff19';c.fillRect(x+4,y+25,sw-8,4);w.fitText(st.name,x+sw/2,y+16,sw-10,anchor?15:18,'#fff9e8');
 if(anchor){w.round(x+8,y+32,sw-16,sh-39,3,'#c9d8cf');for(let i=1;i<4;i++)w.line(x+8+i*(sw-16)/4,y+33,x+8+i*(sw-16)/4,y+sh-8,'#f3f3df',2);w.text('LANDMARK',x+sw/2,y+sh-12,8,'#6c8574');return;}
 const pictures=w.windowPictures?.(st.id)||[];for(let j=0;j<3;j++){const xx=x+8+j*(sw-18)/3,ww=(sw-24)/3,hh=sh-38;w.round(xx,y+31,ww,hh,3,'#f5f1e7');const im=pictures[j]?.image;if(im?.complete&&im.naturalWidth){const k=Math.min((ww-4)/im.naturalWidth,(hh-4)/im.naturalHeight);c.drawImage(im,xx+(ww-im.naturalWidth*k)/2,y+31+(hh-im.naturalHeight*k)/2,im.naturalWidth*k,im.naturalHeight*k);}}

 w.ellipse(st.door.x,st.door.y,8,6,'#d7ab65');
}
export function paintVenue(w,original){const {ctx:c,t}=w,baseWidth=original.id==='carousel'?90:92,baseHeight=original.id==='carousel'?84:64,v={...original,width:baseWidth,height:baseHeight},x=v.x,y=v.y,cx=x+v.width/2,cy=y+v.height/2;w.line(original.x+original.width/2,original.y+original.height/2,v.door.x,v.door.y,'#e9dfc8',12);c.save();c.translate(x,y);c.scale(original.width/baseWidth,original.height/baseHeight);c.translate(-x,-y);w.round(x+3,y+5,v.width,v.height,9,'#4a65562b');w.round(x,y,v.width,v.height,9,'#f0e6cd');
 const bench=(xx,yy)=>{w.round(xx,yy,27,6,2,'#a57c55');w.round(xx,yy-7,27,4,2,'#bb956d');w.line(xx+4,yy+5,xx+4,yy+12,'#54796a',3);w.line(xx+23,yy+5,xx+23,yy+12,'#54796a',3);};
 const table=(xx,yy)=>{w.ellipse(xx,yy,13,9,'#f9f0d8');w.line(xx,yy,xx,yy+15,'#b69b76',3);w.ellipse(xx,yy-2,4,3,'#9e795b');};
 if(['coffee','food','lounge'].includes(v.id)){w.round(x+4,y+4,v.width-8,18,4,v.id==='coffee'?'#69917b':v.id==='food'?'#be8c65':'#9aa46f');for(let j=0;j<5;j++)w.round(x+5+j*17,y+12,8,11,1,'#fff5dd70');table(x+25,y+39);table(x+66,y+40);bench(x+10,y+49);bench(x+54,y+49);w.text(v.id==='coffee'?'COFFEE':v.id==='food'?'FOOD HALL':'TEA',cx,y+16,9,'#fff9df');}
 else if(v.id==='rest'){w.round(x+6,y+6,v.width-12,v.height-12,8,'#d9e2c4');w.ellipse(cx,y+21,18,10,'#6c9796');w.ellipse(cx,y+19,14,7,'#a8d7ce');for(let j=0;j<3;j++)w.ellipse(cx+Math.sin(t*2+j*2)*8,y+16-Math.abs(Math.sin(t*2+j*2))*12,2,3,'#f2fff0');bench(x+9,y+45);bench(x+54,y+45);w.ellipse(x+12,y+15,12,10,'#88a477');w.ellipse(x+80,y+13,12,10,'#a0b98b');}
 else if(v.id==='carousel'){w.ellipse(cx,cy+9,35,23,'#d8b76d');w.line(cx,cy-27,cx,cy+27,'#a58b53',5);for(let i=0;i<5;i++){const a=t*.7+i*Math.PI*2/5,xx=cx+Math.cos(a)*26,yy=cy+Math.sin(a)*13+7;w.line(xx,cy-11,xx,yy,'#ac9464',2);w.round(xx-7,yy-3,14,7,3,'#fff5d9');w.round(xx+3,yy-7,5,7,2,'#fff5d9');}c.fillStyle='#bf8474';c.beginPath();c.moveTo(cx-40,cy-12);c.lineTo(cx,cy-42);c.lineTo(cx+40,cy-12);c.fill();w.line(cx-40,cy-12,cx+40,cy-12,'#e4c785',5);for(let i=0;i<6;i++)w.ellipse(cx-33+i*13,cy-11,2,2,'#fff3b3');}
 else if(v.id==='bridge'){w.round(x+5,y+6,82,51,5,'#9cbeb5');for(let j=0;j<5;j++)w.line(x+10+j*16,y+40,x+24+j*16,y+23,'#cee4d3',2);w.line(x+3,y+34,x+88,y+34,'#d5c29a',18);w.line(x+3,y+23,x+88,y+23,'#8b9d73',3);w.line(x+3,y+44,x+88,y+44,'#8b9d73',3);}
 else if(v.id==='flowers'){w.round(x+7,y+7,78,14,2,'#ba8f79');w.round(x+12,y+28,68,26,3,'#c5b28c');for(let i=0;i<9;i++){const xx=x+17+(i%5)*14,yy=y+29+Math.floor(i/5)*15;w.line(xx,yy,xx,yy+10,'#6a956c',2);w.ellipse(xx,yy,5,5,['#d48f89','#c99fb5','#e4c875'][i%3]);}}
 else if(v.id==='cinema'){w.round(x+5,y+5,82,50,5,'#577578');w.round(x+13,y+12,66,28,2,'#accdbe');w.ellipse(cx+Math.sin(t)*9,y+26,8,8,'#efd2a0');for(let i=0;i<5;i++)w.round(x+15+i*13,y+43,9,9,2,'#be8c77');}
 else if(v.id==='art'){w.round(x+7,y+7,78,48,5,'#dfe5d1');w.ellipse(cx,cy+18,20,5,'#c2cdbb');c.save();c.translate(cx,cy);c.rotate(.15+Math.sin(t*.3)*.03);w.round(-12,-22,11,42,2,'#ba865d');w.round(3,-17,10,32,2,'#78948b');c.restore();}
 else if(v.id==='popup'){w.round(x+7,y+24,78,31,2,'#e0c5a1');c.fillStyle='#c39586';c.beginPath();c.moveTo(x+1,y+25);c.lineTo(cx,y+1);c.lineTo(x+91,y+25);c.fill();for(let i=0;i<4;i++){w.round(x+16+i*18,y+34,11,14,2,['#90a89a','#c9ad75','#d39b92','#b8bd8e'][i]);}}
 else if(v.id==='photo'){w.round(x+23,y+5,46,50,4,'#b8947d');w.round(x+29,y+12,34,35,2,'#d8dcc0');w.text('📷',cx,y+37,22);}
 else{w.round(x+7,y+8,78,46,4,'#b8cabe');w.round(x+12,y+34,68,18,3,'#769c88');w.text('i',cx,y+31,24,'#fff6d9');}
 c.restore();w.fitText(VENUE_LABELS[v.id],original.x+original.width/2,original.y+original.height+13,original.width+18,12,'#506a57');}

export function paintPublicFixture(w,p){const c=w.ctx,theme=themeFor(w.layout.family),x=p.x+p.width/2,y=p.y+p.height/2;if(p.kind==='bench'){c.save();c.translate(x,y);c.rotate(p.rotation);w.round(-33,-12,66,24,4,'#4d634b25');w.round(-32,-8,64,16,3,'#a58c66');w.round(-32,-13,64,5,2,'#c1a47b');for(const z of [-3,2,7])w.line(-30,z,30,z,'#715b4544',1);c.restore();}else if(p.kind==='fountain'){w.ellipse(x,y,18,18,theme.stone);w.ellipse(x,y,14,14,'#8ebbb1');w.ellipse(x,y-8-Math.sin(w.t*2)*2,2,9,'#d3ece2');}else if(p.kind==='kiosk'){w.round(p.x,p.y,p.width,p.height,3,theme.stone);w.round(p.x-3,p.y-5,p.width+6,10,2,theme.accent);w.text({coffee:'☕',photo:'📷',flowers:'💐',popup:'✧'}[p.venue],x,y+8,20,theme.accent);}else if(p.kind==='waystation'){paintWaystation(w,p,theme);}else if(p.kind==='art'){w.round(x-15,y-10,30,20,3,theme.stone);c.save();c.translate(x,y-14);c.rotate(-.35);c.strokeStyle='#ae815a';c.lineWidth=4;c.beginPath();c.ellipse(-4,0,7,14,0,0,Math.PI*2);c.stroke();c.strokeStyle='#5e8b80';c.beginPath();c.ellipse(5,0,7,14,.7,0,Math.PI*2);c.stroke();c.restore();}else if(p.kind==='commons'){w.round(x-15,y-12,30,24,3,theme.stone);if(p.activity==='garden'){w.ellipse(x,y-6,12,11,theme.plant);w.ellipse(x-5,y-12,4,4,theme.flowers);}else if(p.activity==='reading'){w.round(x-11,y-22,22,20,2,theme.trim);for(let i=0;i<4;i++)w.round(x-9+i*5,y-19,4,15,1,['#b87d68','#719685','#d4b465','#879bb0'][i]);}else paintMosaicStudy(w,x,y,theme);}else if(p.kind==='directory'){w.round(x-9,y-28,18,34,2,theme.trim);w.round(x-7,y-25,14,25,1,'#eee6d0');w.line(x-5,y-18,x+5,y-7,theme.accent,2);}else{w.ellipse(x+3,y+6,23,17,'#455b4029');w.ellipse(x,y,18,15,theme.stone);w.ellipse(x,y-10,p.kind==='tree'?25:17,p.kind==='tree'?22:13,theme.plant);w.ellipse(x-7,y-14,12,11,'#84a378');}}
